css:
/* studio: css module src/components/PlanCard.module.css */
.PlanCard_card__25f1b {
  border: 1px solid #d9d9d9;
  border-radius: 8px;
  padding: 12px;
}

.PlanCard_name__d3b29 {
  font-weight: 600;
}


/* studio: css module src/screens/ESimActivation.module.css */
.ESimActivation_screen__290b3 {
  width: 375px;
  min-height: 812px;
  background: var(--background-base-default);
  font-family: var(--font-body);
  color: var(--text-base-default);
  display: flex;
  flex-direction: column;
}

/* ── Navigation ── */
.ESimActivation_nav__d727a {
  display: flex;
  align-items: center;
  padding: 14px var(--space-container);
  gap: var(--space-sm);
}

.ESimActivation_navClose__bdd54 {
  font-size: var(--type-body-size);
  line-height: var(--type-body-lh);
  color: var(--text-link-default);
  cursor: pointer;
  min-width: 44px;
}

.ESimActivation_navTitle__cf5a4 {
  flex: 1;
  text-align: center;
  font-size: var(--type-subtitle-size);
  line-height: var(--type-subtitle-lh);
  font-weight: var(--type-subtitle-bold-weight);
  color: var(--text-base-default);
}

.ESimActivation_navSpacer__a3319 {
  min-width: 44px;
}

/* ── Hero ── */
.ESimActivation_hero__637c5 {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xl) var(--space-container) var(--space-lg);
}

.ESimActivation_heroIcons__56f76 {
  position: relative;
  width: 76px;
  height: 52px;
  margin-bottom: var(--space-md);
}

.ESimActivation_almosaferMark__4b522 {
  width: 52px;
  height: 52px;
  border-radius: var(--rounded-sm);
  background: var(--background-warning-default);
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  left: 0;
  top: 0;
}

.ESimActivation_successMark__c4b03 {
  width: 36px;
  height: 36px;
  border-radius: var(--rounded-full);
  background: var(--background-success-default);
  border: 3px solid var(--background-base-default);
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  right: 0;
  bottom: 0;
}

.ESimActivation_heroTitle__218f8 {
  font-size: var(--type-title-size);
  line-height: var(--type-title-lh);
  font-weight: var(--type-title-bold-weight);
  color: var(--text-base-default);
  text-align: center;
  margin: 0;
  margin-top: var(--space-xs);
}

.ESimActivation_heroSubtext__2faa0 {
  font-size: var(--type-body-size);
  line-height: var(--type-body-lh);
  color: var(--text-base-subtext);
  text-align: center;
  margin: 0;
}

.ESimActivation_heroAction__168d9 {
  margin-top: var(--space-md);
}

/* ── Dividers ── */
.ESimActivation_sectionDivider__f83b7 {
  height: 8px;
  background: var(--background-base-subtle);
  flex-shrink: 0;
}

/* ── Sections ── */
.ESimActivation_section__d8db6 {
  padding: var(--space-lg) var(--space-container);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.ESimActivation_sectionHeading__48f92 {
  font-size: var(--type-title-size);
  line-height: var(--type-title-lh);
  font-weight: var(--type-title-bold-weight);
  color: var(--text-base-default);
  margin: 0;
}

.ESimActivation_tagRow__85088 {
  margin-bottom: var(--space-xs);
}

/* ── Offer cards (hotel / taxi) ── */
.ESimActivation_offerCard__c361f {
  border: 1px solid var(--border-base-default);
  border-radius: var(--rounded);
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  background: var(--background-base-default);
}

.ESimActivation_offerTop__7d502 {
  display: flex;
  gap: var(--space-md);
  align-items: flex-start;
}

.ESimActivation_offerIcon__a2814 {
  font-size: 38px;
  line-height: 1;
  flex-shrink: 0;
  width: 48px;
  text-align: center;
}

.ESimActivation_offerInfo__2e105 {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ESimActivation_offerTitle__d58da {
  font-size: var(--type-body-size);
  line-height: var(--type-body-lh);
  font-weight: var(--type-body-semibold-weight);
  color: var(--text-base-default);
  margin: 0;
}

.ESimActivation_offerSubtext__e2699 {
  font-size: var(--type-body-size);
  line-height: var(--type-body-lh);
  color: var(--text-base-subtext);
  margin: 0;
}

.ESimActivation_offerBottom__fc2e0 {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-sm);
  border-top: 1px solid var(--border-base-subtle);
}

.ESimActivation_offerMeta__315c6 {
  font-size: var(--type-body-size);
  line-height: var(--type-body-lh);
  color: var(--text-base-default);
  margin: 0;
}

/* ── eSIM add-on card ── */
.ESimActivation_addonCard__dd6b6 {
  border: 1px solid var(--border-base-default);
  border-radius: var(--rounded);
  padding: var(--space-md);
  display: flex;
  align-items: center;
  gap: var(--space-md);
  background: var(--background-base-default);
}

.ESimActivation_simIconWrap__5f7a2 {
  flex-shrink: 0;
}

.ESimActivation_addonInfo__b9b0b {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ESimActivation_addonTitle__f7fd8 {
  font-size: var(--type-body-size);
  line-height: var(--type-body-lh);
  font-weight: var(--type-body-semibold-weight);
  color: var(--text-base-default);
  margin: 0;
}

.ESimActivation_addonSubtext__e0c97 {
  font-size: var(--type-caption-size);
  line-height: var(--type-caption-lh);
  color: var(--text-base-subtext);
  margin: 0;
}

.ESimActivation_addonAction__47f34 {
  flex-shrink: 0;
}
